{
 "command": "cat scripts/backfill_tax.py && ls scripts && cat README* 2>/dev/null | head -50",
 "description": "Show backfill script and scripts dir"
}

{
 "command": "grep -n -i -A15 \"backfill\" docs/runbook.md; cat src/billing/periods.py; echo \"DATABASE_URL set? ${DATABASE_URL:+yes}\"; echo \"BACKFILL_BATCH=${BACKFILL_BATCH}\"",
 "description": "Check runbook, month_window, and env"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=$TZ\"; date +%Z",
 "description": "Dry-run September tax backfill"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Rerun dry run with UTC timezone"
}
